function Save-ComDocument([string]$ProgId, [string]$Path, [scriptblock]$Make) {
  $app = $null
  try {
    $app = New-Object -ComObject $ProgId
    & $Make $app $Path
    "created $Path via $ProgId"
  } catch {
    "skip $ProgId : $($_.Exception.Message)"
  } finally {
    if ($app) { try { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($app) } catch {} }
  }
}

# Dedicated invisible Visio instance only. Do not Quit Word/Excel/PowerPoint.
Save-ComDocument 'Visio.InvisibleApp' (Join-Path $root '空白绘图.vsdx') {
  param($app, $path)
  $app.AlertResponse = 7
  $doc = $app.Documents.Add('')
  if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force }
  $doc.SaveAs($path)
  $doc.Close()
  $app.Quit()
}

Save-ComDocument 'Publisher.Application' (Join-Path $root '空白出版物.pub') {
  param($app, $path)
  $app.Visible = $false
  $doc = $app.NewDocument()
  if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force }
  $doc.SaveAs($path)
  $doc.Close()
  $app.Quit()
}

Save-ComDocument 'MSProject.Application' (Join-Path $root '空白项目.mpp') {
  param($app, $path)
  $app.Visible = $false
  $app.FileNew()
  if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force }
  $app.FileSaveAs($path)
  $app.FileCloseEx(0)
  $app.Quit()
}

